def budget(total, bad, target):
    if total < 0 or bad < 0 or bad > total:
        raise ValueError("contagens invalidas")
    if not 0 < target < 1:
        raise ValueError("meta invalida")
    if total == 0:
        return None
    allowed = total * (1 - target)
    return (allowed - bad) / allowed

def diferencas(desejados, existentes):
    alvo = set(desejados)
    atual = set(existentes)
    return {
        "criar": sorted(alvo - atual),
        "revisar_remocao": sorted(atual - alvo),
        "manter": sorted(alvo & atual),
    }

assert diferencas(["a", "b"], ["b", "c"]) == {
    "criar": ["a"],
    "revisar_remocao": ["c"],
    "manter": ["b"],
}

def unir_intervalos(intervalos):
    ordenados = sorted(intervalos)
    unidos = []
    for inicio, fim in ordenados:
        if fim < inicio:
            raise ValueError("intervalo invertido")
        if not unidos or inicio > unidos[-1][1]:
            unidos.append([inicio, fim])
        else:
            unidos[-1][1] = max(unidos[-1][1], fim)
    return [tuple(x) for x in unidos]

def espera_retry(tentativa, restante, sorteio):
    if tentativa < 0 or restante <= 0:
        return None
    teto = min(0.1 * (2 ** min(tentativa, 8)), 2.0)
    espera = teto * sorteio
    if not 0 <= sorteio <= 1:
        raise ValueError("sorteio fora da faixa")
    if espera >= restante:
        return None
    return espera

